// find the pipeline channel by name; a 30-minute window (dedupe by ts keeps it idempotent)
const want = 'etsy-shop-alerts';
const chans = ($input.first().json.channels || []);
const ch = chans.find(c => c.name === want);
if (!ch) throw new Error(`channel ${want} not visible to the bot — invite it with /invite`);
return [{ json: { channel: ch.id, oldest: (Date.now() / 1000 - 1800).toFixed(3) } }];

// David's verdicts: top-level messages AND thread replies. "approve R306" / "revise R306: …" / "reject R306";
// inside a thread a bare "approve" takes the SKU from the parent message ("R306 pilot is ready …").
const st = $getWorkflowStaticData('global'); st.seen = st.seen || [];
const top = ($('Channel history').first().json.messages || []);
const byTs = {}; for (const m of top) byTs[m.ts] = m;
const all = [];
for (const m of top) all.push({ m, parent: null });
for (const it of $('Thread replies').all()) {
  const arr = (it.json.messages || []);
  for (const m of arr) { if (m.thread_ts && m.ts !== m.thread_ts) all.push({ m, parent: byTs[m.thread_ts] || arr.find(x => x.ts === m.thread_ts) || null }); }
}
const out = [];
for (const { m, parent } of all) {
  if (m.bot_id || (m.subtype && m.subtype !== 'file_share' && m.subtype !== 'thread_broadcast')) continue;
  if (st.seen.includes(m.ts)) continue;
  const t = String(m.text || '').trim();
  const mm = t.match(/^(approve|approved|revise|revised|reject|rejected)\b\s*(R\d{2,4})?\b[\s:\-–—]*([\s\S]*)$/i);
  if (!mm) continue;
  let sku = (mm[2] || '').toUpperCase();
  if (!sku && parent) { const pm = String(parent.text || '').match(/\b(R\d{2,4})\b/); if (pm) sku = pm[1].toUpperCase(); }
  if (!sku) continue;
  st.seen.push(m.ts); if (st.seen.length > 300) st.seen = st.seen.slice(-300);
  const verdict = mm[1].toLowerCase().replace(/d$/, '').replace('approve', 'approve');
  out.push({ json: { ts: m.ts, user: m.user, verdict: verdict.startsWith('approv') ? 'approve' : (verdict.startsWith('revis') ? 'revise' : 'reject'), sku, note: (mm[3] || '').trim(), text: t } });
}
return out;

// join each verdict with its sheet row; only a row in "Design For Review" takes a verdict
const rows = $('Read R Designs').first().json.values || [];
const hdr = rows[0] || [];
const iSku = hdr.indexOf('SKU'), iSt = hdr.indexOf('STATUS'), iH = hdr.indexOf('Approval/Revision Notes');
const col = i => String.fromCharCode(65 + i);
const out = [];
for (const it of $('Parse verdicts').all()) {
  const v = it.json; const r = rows.findIndex((row, k) => k > 0 && (row[iSku] || '').trim() === v.sku);
  if (r < 0) { out.push({ json: { ...v, do_write: false, text_out: `${v.sku} is not on the R Designs sheet` } }); continue; }
  const status = (rows[r][iSt] || '').trim();
  if (status !== 'Design For Review') { out.push({ json: { ...v, do_write: false, text_out: `${v.sku} is not waiting for a verdict (status: ${status || 'blank'})` } }); continue; }
  const rowNum = r + 1; const newStatus = v.verdict === 'approve' ? 'Ready for Mock-up' : 'Revise';
  const batch = { valueInputOption: 'RAW', data: [
    { range: `R Designs!${col(iSt)}${rowNum}`, values: [[newStatus]] },
    { range: `R Designs!${col(iH)}${rowNum}`, values: [[`David via Slack ${new Date().toISOString().slice(0,16)}: ${v.text}`]] } ] };
  out.push({ json: { ...v, do_write: true, batch, text_out: `recorded ${v.verdict} for ${v.sku} → status ${newStatus}; the next hourly tick acts on it` } });
}
return out;

// threads with recent replies are read separately (conversations.replies); always emit one valid ts so the flow continues
const ch = $('Pick channel').first().json; const msgs = ($input.first().json.messages || []);
const out = [];
for (const m of msgs) {
  if (m.reply_count && m.latest_reply && parseFloat(m.latest_reply) >= parseFloat(ch.oldest)) out.push({ json: { channel: ch.channel, ts: m.thread_ts || m.ts, oldest: ch.oldest } });
}
if (!out.length && msgs.length) out.push({ json: { channel: ch.channel, ts: msgs[0].ts, oldest: ch.oldest } });
if (!out.length) out.push({ json: { channel: ch.channel, ts: '0', oldest: ch.oldest } });
return out;
